import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums for main items ---
  it("quotes an empty item list — premium 5 G (processing fee only)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("quotes a plain sword for a new customer — 100 G base + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes a plain amulet for a new customer — 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("quotes a plain staff for a new customer — 80 G base + 8 G first insurance + 5 G fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("quotes a plain potion for a new customer — 40 G base + 4 G first insurance + 5 G fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Quote: components and the block of 3 alike ---
  it("quotes 1 rune — 25 G base premium (+ 2.5 first insurance + 5 fee = 32.5 → 33 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it.todo("quotes 2 runes — 50 G base premium (no block)");
  it.todo("quotes 3 runes — 60 G base premium (block applies)");
  it.todo("quotes 4 runes — 100 G base premium (no block — block requires exactly 3)");
  it.todo("quotes 7 runes — 175 G base premium");
  it.todo("quotes 2 runes + 1 moonstone — 75 G base premium (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones — 120 G base premium (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed sword — 100 G base + 50 G curse");
  it.todo("adds a 30 % high-enchantment surcharge to a sword with enchantment 5");
  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies the 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies the 10 % first insurance surcharge to the policy base premium");
  it.todo("applies the 15 % follow-up discount to every contract after the customer's first");
  it.todo("adds the 5 G processing fee at the very end of every premium");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item's base premium — cursed sword + plain amulet → 160 G base + 50 G curse");

  // --- Quote: rounding in MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed sword (steel, enchantment 3) — 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword with enchantment 7 — 160 G");

  // --- Quote: errors ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick)");

  // --- Claim: standard reimbursement ---
  it.todo("pays a regular sword (steel, enchantment 3) with damage 500 G — payout 400 G (damage minus 100 G deductible)");
  it.todo("pays damage 200 G to a rune — payout 100 G (runes have no enchantment or material)");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment 8 at 50 % — dragon sword, damage 1000 G → payout 400 G");
  it.todo("fully reimburses dragon-material damage — dragon sword, enchantment 5, damage 800 G → payout 700 G");
  it.todo("lets the 50 % rule win when both clauses apply — dragon sword, enchantment 9, damage 1000 G → payout 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword with enchantment 9, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item — sword 500 G + amulet 300 G → payout 600 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy at twice the insurance sum — sword + amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values — cursed sword → cap 2000 G despite premium modifiers");
  it.todo("bases the insurance sum on full component values — sword + 3 runes → insurance sum 1750 G despite the block discount");
  it.todo("reduces a payout to the remaining cap across successive claims — two 1500 G claims on a sword → 1400 G then 600 G");
  it.todo("reports the remaining cap after each claim");

  // --- Claim: multiple items of the same type ---
  it.todo("insures two swords — insurance sum 2000 G, cap 4000 G");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers");

  // --- Claim: rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Claim: errors ---
  it.todo("rejects a claim whose damage references an item not covered by the policy");
  it.todo("rejects a claim whose damage references an unknown item type");
  it.todo("rejects a claim containing a damage entry with a negative amount");

  // --- Scenario / CLI wiring ---
  it.todo("returns one result per step, in order, for a mixed quote-and-claim scenario");
});

