  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const runes = quote.items.filter((item) => item.type === "rune");
  const basePremium =
    runes.length === 3
      ? COMPONENT_BLOCK_BASE_PREMIUM
      : quote.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const modifiedPremium =
    basePremium + percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return {
    results: [{ premium: Math.ceil(modifiedPremium + PROCESSING_FEE) }],
  };
};

