export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

/**
 * Added at the very end of every premium, after all percentage modifiers, so
 * no surcharge or discount is ever computed on top of it.
 */
const PROCESSING_FEE = 5;

/**
 * Rates are kept as exact numerator/denominator fractions rather than float
 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
 * only the final premium is rounded.
 */
const percent = (amount: number, rate: number): number => (amount * rate) / 100;

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** A building block of 3 alike components is offered at this base premium. */
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_BLOCK_SIZE = 3;

/**
 * Knowingly incomplete: only recognises a block when the *whole* quote is
 * exactly 3 runes. Grouping by component type, and blocks alongside other
 * items, are not driven by a test yet.
 */
const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => item.type === "rune");

const sumOfItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const basePremium = formsComponentBlock(quote.items)
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : sumOfItemPremiums(quote.items);
  const premiumAfterPercentageModifiers =
    basePremium + percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return {
    results: [
      { premium: Math.ceil(premiumAfterPercentageModifiers + PROCESSING_FEE) },
    ],
  };
};

