    sword: { basePremium: 100, isComponent: false },
    amulet: { basePremium: 60, isComponent: false },
    staff: { basePremium: 80, isComponent: false },
    potion: { basePremium: 40, isComponent: false },
    rune: { basePremium: 25, isComponent: true },
    moonstone: { basePremium: 25, isComponent: true },
  };

/** A building block of 3 alike components is offered at this base premium. */
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_BLOCK_SIZE = 3;

/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
const countByType = (items: Item[]): [string, number][] => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return [...counts];
};

/**
 * Prices every item of one type together, because exactly 3 alike components
 * form a block charged as one. "Alike" means the same type, and the block does
 * not repeat: 4 or 7 runes are each priced per item.
