 * Prices every item of one type together, because exactly 3 alike components
 * form a block charged as one. "Alike" means the same type, and the block does
 * not repeat: 4 or 7 runes are each priced per item.
 */
const basePremiumForType = (type: string, count: number): number => {
  const { basePremium, isComponent } = ITEM_TYPES[type];
  return isComponent && count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : count * basePremium;
};

const sumOfBasePremiums = (items: Item[]): number =>
  countByType(items).reduce(
    (sum, [type, count]) => sum + basePremiumForType(type, count),
    0,
  );

/**
 * Item-specific modifiers are charged on the affected item's own base premium,
 * not on the policy total.
 */
const sumOfItemSurcharges = (items: Item[]): number =>
  items.reduce(
    (sum, item) =>
      item.cursed
        ? sum + percent(ITEM_TYPES[item.type].basePremium, CURSE_SURCHARGE_PERCENT)
        : sum,
    0,
  );

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const basePremium = sumOfBasePremiums(quote.items);
  const premiumAfterPercentageModifiers =
    basePremium +
    sumOfItemSurcharges(quote.items) +
    percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
