    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].basePremium, rate),
    0,
  );

const sumOfItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargeForItem(item), 0);

/**
 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
 * premium (the sum of item base premiums, before any item surcharge), so no
 * modifier is ever computed on top of another. Discounts carry a negative rate.
 */
const POLICY_MODIFIERS: {
  appliesTo: (customer: Customer) => boolean;
  rate: number;
}[] = [{ appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT }];

const sumOfPolicyAdjustments = (
  customer: Customer,
  policyBasePremium: number,
): number =>
  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(customer)).reduce(
    (sum, { rate }) => sum + percent(policyBasePremium, rate),
    0,
  );

const premiumFor = (customer: Customer, items: Item[]): number => {
  const policyBasePremium = sumOfBasePremiums(items);
  return Math.ceil(
    policyBasePremium +
      sumOfItemSurcharges(items) +
      sumOfPolicyAdjustments(customer, policyBasePremium) +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  return {
    results: [{ premium: premiumFor(scenario.customer, quote.items) }],
  };
};

